#!/bin/bash
# Одноразовое напоминание: инфра-задача Творим PPC (tasks #2/#4). Само-удаляется после отправки.
TOKEN=$(python3 -c "import json;print(json.load(open('$HOME/artvision-data/tokens.json'))['telegram']['portal_bot']['token'])" 2>/dev/null)
CHAT=161261562
MSG=$'\xe2\x8f\xb0 12:00 \xe2\x80\x94 \xd1\x81\xd1\x82\xd0\xb0\xd1\x80\xd1\x82 \xd0\xbe\xd1\x82\xd0\xbb\xd0\xbe\xd0\xb6\xd0\xb5\xd0\xbd\xd0\xbd\xd0\xbe\xd0\xb9 \xd0\xb7\xd0\xb0\xd0\xb4\xd0\xb0\xd1\x87\xd0\xb8: \xd0\xa2\xd0\xb2\xd0\xbe\xd1\x80\xd0\xb8\xd0\xbc PPC \xd0\xb8\xd0\xbd\xd1\x84\xd1\x80\xd0\xb0. tasks #2 (\xd0\xb0\xd0\xb2\xd1\x82\xd0\xbe-\xd1\x80\xd0\xb5\xd0\xb7\xd0\xba\xd0\xb0 \xd0\xbf\xd0\xbb\xd0\xbe\xd1\x89\xd0\xb0\xd0\xb4\xd0\xbe\xd0\xba) + #4 (\xd1\x81\xd1\x82\xd0\xb0\xd0\xbd\xd0\xb4\xd0\xb0\xd1\x80\xd1\x82 \xd0\xba\xd0\xbe\xd0\xbd\xd1\x82\xd0\xb5\xd0\xba\xd1\x81\xd1\x82-\xd1\x84\xd0\xb0\xd0\xb9\xd0\xbb\xd0\xbe\xd0\xb2). \xd0\xa7\xd0\xb8\xd1\x82\xd0\xb0\xd0\xb9 ppc-context.md + context-log (10.06). \xd0\xa1\xd1\x82\xd1\x80\xd0\xb0\xd1\x82\xd0\xb5\xd0\xb3\xd0\xb8\xd1\x8e \xd0\xa0\xd0\xa1\xd0\xaf v2 \xd0\x9d\xd0\x95 \xd0\xbc\xd0\xb5\xd0\xbd\xd1\x8f\xd1\x82\xd1\x8c \xe2\x80\x94 \xd1\x80\xd0\xb5\xd0\xb7\xd0\xb0\xd1\x82\xd1\x8c \xd0\xbf\xd0\xbb\xd0\xbe\xd1\x89\xd0\xb0\xd0\xb4\xd0\xba\xd0\xb8. \xd0\xa1\xd0\xba\xd0\xb0\xd0\xb6\xd0\xb8 \xc2\xab\xd0\xb3\xd0\xbe\xc2\xbb.'
if [ -n "$TOKEN" ]; then
  curl -s "https://api.telegram.org/bot${TOKEN}/sendMessage" --data-urlencode "chat_id=${CHAT}" --data-urlencode "text=${MSG}" >/dev/null
fi
# self-destruct (одноразовое)
PLIST="$HOME/Library/LaunchAgents/pro.artvision.tvorim-infra-reminder.plist"
launchctl unload "$PLIST" 2>/dev/null
rm -f "$PLIST"
